#!/usr/bin/env python3
"""One-command updater for the ALBA ONE Next.js 15 Enterprise Decision OS UI."""
import base64, json, zlib
from pathlib import Path

B64 = ""
here = Path(__file__).resolve().parent
root = (here / "apps" / "web") if (here / "apps" / "web").exists() else (here.parent / "apps" / "web")
data = json.loads(zlib.decompress(base64.b64decode(B64)).decode("utf-8"))
for rel, content in data.items():
    target = root / rel
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")
    print("Updated:", target)
print("Successfully updated all ALBA ONE frontend files in:", root)